-- 00113_pregnancy_alert_rules.sql — Pregnancy alerts through the message engine (T-M10-08, D-165; DECISIONS.md M-10,
-- H-02; SPEC §5.4.1, §4.2). Data only (no schema change), so no Laravel twin: Laravel never serves the inbox.
--
-- 1. One approved message rule per pregnancy alert in the alerts_inbox slot (rule_key preg.<name>; the safety rules
--    locked). The rows are generated from internal/messages/pregnancyalerts/inboxalerts (Defs + copy/<code>.json: the
--    default language fa as the base, content.translations.en) and pinned by its migration int test. The copy is
--    today's pregnancy_alert / emergency copy (00005, 00008, 00033, T-M9-05) with the variables renamed to the
--    preg_* evidence variables; every rule is listed for the advisor in docs/engine-v6/clinical-signoff.md.
--    ON DUPLICATE KEY keeps a database whose rules were already seeded (or edited) as it is.
-- 2. The v2 pregnancy_alerts rows (alert_type 'v2:<rule>') move into message_inbox (legacy_alert_id = the old id;
--    the old rows stay for the legacy /pregnancy/alerts list). Per user and rule the newest row of the last 30 days
--    is the open row (acked → acknowledged, read without ack = added to the visit note → added_to_visit_note, else
--    active); any other row is history (older than 30 days → archived, else resolved). The evidence variables are
--    mapped from the v2 vars so a migrated row renders. Idempotent (a row already moved is skipped); Down removes
--    the migrated rows only, then the seeded rules.

-- +goose Up
INSERT INTO `message_rules` (rule_key, title, level, kind, priority, placement, content, conditions, exceptions,
  variants_enabled, ab_split, cap_count, cap_period, cooldown_days, audience_percent, status, is_active, version,
  approved_version, locked, created_at, updated_at)
VALUES
('preg.vomiting', 'Pregnancy: repeated vomiting', 'worth_followup', 'clinical', 600, 'alerts_inbox', '{"a":{"title":"استفراغ در {preg_vomit_days} روز از ۷ روز اخیر","body":"تهوع و استفراغ در این هفته‌ها رایجه. اگه نمی‌تونی مایعات رو نگه داری، ادرارت خیلی کم شده، یا وزن کم می‌کنی، بهتره با پزشک یا مامات در میون بذاری."},"seen":"استفراغ در {preg_vomit_days} روز از ۷ روز اخیر، {preg_vomit_severe} روزش با شدت «شدید»","confidence":"این الگو از ثبت‌های خودته، نه تشخیص","translations":{"en":{"a":{"title":"Vomiting on {preg_vomit_days} of the last 7 days","body":"Nausea and vomiting are common in these weeks. If you can''t keep fluids down, you pee very little, or you are losing weight, it is worth talking to your doctor or midwife."},"seen":"Vomiting on {preg_vomit_days} of the last 7 days, {preg_vomit_severe} of them severe","confidence":"This pattern comes from your own logs, not a diagnosis"}}}', '[{"op":"or","items":[{"fact":"preg.vomiting_days_7","op":"gte","value":4},{"fact":"preg.vomiting_severe_7","op":"gte","value":2},{"fact":"preg.vomiting_streak","op":"gte","value":3}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.cant_keep_fluids', 'Pregnancy: can''t keep fluids down', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"مایعات در بدنت نمی‌ماند","body":"وقتی هیچ مایعی در بدنت نمی‌ماند، زود کم‌آب می‌شوی. همین امروز با پزشک یا ماما تماس بگیر."},"seen":"ثبت کردی که نمی‌توانی مایعات را نگه داری.","confidence":"این از ثبت خودت است؛ فقط پزشک می‌تواند علتش را بگوید.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"You can''t keep fluids down","body":"When no fluids stay down, you can get dehydrated quickly. Contact your doctor or midwife today."},"seen":"You logged that you can''t keep fluids down.","confidence":"This comes from your own log; only a doctor can tell the cause.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.cant_keep_fluids","op":"eq","value":true}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.severe_symptoms', 'Pregnancy: severe symptoms this week', 'worth_followup', 'clinical', 550, 'alerts_inbox', '{"a":{"title":"{preg_severe_count} علامت شدید در یک هفته","body":"علائم شدیدِ تکرارشونده ارزش داره که در ویزیت بعدی مطرح بشه. اگه روزمره‌ات رو مختل کرده، زودتر با پزشکت صحبت کن."},"seen":"در ۷ روز اخیر {preg_severe_count} بار علامتی با شدت «شدید» ثبت کردی","confidence":"این الگو از ثبت‌های خودته، نه تشخیص","translations":{"en":{"a":{"title":"{preg_severe_count} severe symptoms this week","body":"Repeated severe symptoms are worth raising at your next visit. If they disrupt your daily life, talk to your doctor sooner."},"seen":"You logged a severe symptom {preg_severe_count} times in the last 7 days","confidence":"This pattern comes from your own logs, not a diagnosis"}}}', '[{"op":"and","items":[{"fact":"preg.severe_symptoms_7","op":"gte","value":3}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.critical_symptom', 'Pregnancy: critical symptom', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"{preg_symptoms} ثبت شده است","body":"این علامت را نادیده نگیر. همین حالا با پزشک یا ماما تماس بگیر."},"seen":"«{preg_symptoms}» را ثبت کردی ({preg_symptom_on}).","confidence":"این علامت از ثبت خودت است؛ فقط پزشک می‌تواند علتش را بگوید.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"{preg_symptoms} logged","body":"Don''t ignore this symptom. Contact your doctor or midwife now."},"seen":"You logged \\"{preg_symptoms}\\" ({preg_symptom_on}).","confidence":"This comes from your own log; only a doctor can tell the cause.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.critical_symptom","op":"in","value":["bleeding","fluid_leakage","severe_sudden_pain","spotting"]}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.weight_missing', 'Pregnancy: weight not logged this week', 'suggestion', 'product', 50, 'alerts_inbox', '{"a":{"title":"وزن این هفته ثبت نشده","body":"اگه یک بار در هفته وزن رو ثبت کنی، روند وزن برای ویزیت‌هات کامل‌تر می‌شه. ثبت نکردنش هم اشکالی نداره."},"seen":"در هفتهٔ {preg_week} هنوز وزنی ثبت نکردی","confidence":"فقط یک یادآوره","translations":{"en":{"a":{"title":"This week''s weight isn''t logged","body":"Logging your weight once a week makes the trend more complete for your visits. It''s fine to skip it too."},"seen":"No weight logged yet in week {preg_week}","confidence":"Just a reminder"}}}', '[{"op":"and","items":[{"fact":"preg.days_since_weight","op":"gte","value":7}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.week_entered', 'Pregnancy: new week', 'info', 'content', 150, 'alerts_inbox', '{"a":{"title":"وارد هفتهٔ {preg_week} شدی","body":"مبنای محاسبه هنوز {preg_basis}ه. بعد از سونوگرافی NT می‌تونی مبنا رو به‌روز کنی تا بازهٔ تخمین محدودتر بشه."},"seen":"هفتهٔ {preg_week} بارداری از {preg_week_on} شروع شده","confidence":"بر اساس مبنای محاسبهٔ فعلی ({preg_basis})","translations":{"en":{"a":{"title":"You''ve entered week {preg_week}","body":"Your dating basis is still {preg_basis}. After the NT scan you can update it to narrow the estimate range."},"seen":"Pregnancy week {preg_week} started on {preg_week_on}","confidence":"Based on your current dating basis ({preg_basis})"}}}', '[{"op":"and","items":[{"fact":"pregnancy_week","op":"gte","value":1}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
