('preg.fetal_movement', 'Pregnancy: reduced or no fetal movement', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"حرکات جنین کم شده است","body":"کم‌شدن یا قطع حرکات جنین نباید تا فردا صبر کند. همین حالا با پزشک یا ماما تماس بگیر یا به بیمارستان برو."},"seen":"حرکات جنین را «{preg_fetal_status}» ثبت کردی ({preg_fetal_on}).","confidence":"این از ثبت خودت است؛ فقط معاینه می‌تواند حال جنین را مشخص کند.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"Fewer baby movements","body":"Fewer or no movements should not wait until tomorrow. Contact your doctor or midwife now, or go to the hospital."},"seen":"You logged baby movements as \\"{preg_fetal_status}\\" ({preg_fetal_on}).","confidence":"This is your own log; only an exam can check on the baby.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.fetal_movement","op":"in","value":["reduced","none"]}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.fetal_movement_kicks', 'Pregnancy: kick count short of the target', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"در {preg_kick_minutes} دقیقه کمتر از {preg_kick_target} حرکت شمردی","body":"همین حالا با پزشک یا ماما تماس بگیر. منتظر نمان که حرکت‌ها خودشان برگردند و شمارش را به فردا نینداز."},"seen":"در شمارشِ {preg_kick_at}، {preg_kick_count} حرکت ثبت کردی؛ هدف، {preg_kick_target} حرکت در {preg_kick_minutes} دقیقه است.","confidence":"این از شمارش خودت است و تشخیص نیست؛ فقط معاینه می‌تواند حال جنین را مشخص کند.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"Fewer than {preg_kick_target} movements in {preg_kick_minutes} minutes","body":"Contact your doctor or midwife now. Don''t wait for the movements to come back, and don''t leave it until tomorrow."},"seen":"In the count of {preg_kick_at} you logged {preg_kick_count} movements; the aim is {preg_kick_target} movements within {preg_kick_minutes} minutes.","confidence":"This comes from your own count and is not a diagnosis; only an exam can check on the baby.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.fetal_movement","op":"eq","value":"low_session"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.bp_high', 'Pregnancy: BP ≥ 140/90 (follow-up level)', 'worth_followup', 'clinical', 700, 'alerts_inbox', '{"a":{"title":"فشار خون بالا ثبت شده است","body":"فشار ۱۴۰/۹۰ یا بالاتر در بارداری باید زود بررسی شود. چند دقیقه استراحت کن، دوباره اندازه بگیر و امروز با پزشکت تماس بگیر."},"seen":"فشار {preg_bp_sys}/{preg_bp_dia} ثبت کردی ({preg_bp_on}).","confidence":"این یک عدد از ثبت خودت است؛ اندازه‌گیری دوباره در حال استراحت کمک می‌کند.","translations":{"en":{"a":{"title":"High blood pressure logged","body":"A reading of 140/90 or higher in pregnancy should be checked soon. Rest a few minutes, measure again and contact your doctor today."},"seen":"You logged {preg_bp_sys}/{preg_bp_dia} ({preg_bp_on}).","confidence":"One reading from your own log; measuring again at rest helps."}}}', '[{"op":"and","items":[{"fact":"preg.bp_last_category","op":"eq","value":"high"},{"fact":"preg.bp_high_level","op":"eq","value":"follow_up"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.bp_high_urgent', 'Pregnancy: BP ≥ 140/90 (urgent level)', 'follow_soon', 'clinical', 790, 'alerts_inbox', '{"a":{"title":"فشار خون بالا ثبت شده است","body":"فشار ۱۴۰/۹۰ یا بالاتر در بارداری باید زود بررسی شود. چند دقیقه استراحت کن، دوباره اندازه بگیر و با پزشکت تماس بگیر."},"seen":"فشار {preg_bp_sys}/{preg_bp_dia} ثبت کردی ({preg_bp_on}).","confidence":"این یک عدد از ثبت خودت است؛ اندازه‌گیری دوباره در حال استراحت کمک می‌کند.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"High blood pressure logged","body":"A reading of 140/90 or higher in pregnancy should be checked soon. Rest a few minutes, measure again and contact your doctor."},"seen":"You logged {preg_bp_sys}/{preg_bp_dia} ({preg_bp_on}).","confidence":"One reading from your own log; measuring again at rest helps.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.bp_last_category","op":"eq","value":"high"},{"fact":"preg.bp_high_level","op":"eq","value":"urgent"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.bp_severe', 'Pregnancy: BP ≥ 160/110', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"فشار خونت در محدودهٔ شدید بارداری است","body":"همین حالا با پزشک یا ماما تماس بگیر یا به بیمارستان برو. اگر سردرد شدید، تاری دید، درد بالای شکم یا تنگی نفس داری، با اورژانس ۱۱۵ تماس بگیر."},"seen":"فشار {preg_bp_sys}/{preg_bp_dia} ثبت کردی ({preg_bp_on})؛ ۱۶۰/۱۱۰ یا بالاتر در بارداری فوری است.","confidence":"این یک عدد از ثبت خودت است؛ با این عدد منتظر اندازه‌گیری دوباره نمان.","contact":"همین حالا با پزشک یا ماما تماس بگیر؛ اگر در دسترس نیستند یا حالت بدتر شد، با اورژانس ۱۱۵ تماس بگیر.","translations":{"en":{"a":{"title":"Your blood pressure is in the severe range for pregnancy","body":"Contact your doctor or midwife now, or go to the hospital. If you have a severe headache, blurred vision, pain high in your belly or trouble breathing, call emergency services (115)."},"seen":"You logged {preg_bp_sys}/{preg_bp_dia} ({preg_bp_on}); 160/110 or higher in pregnancy is urgent.","confidence":"One reading from your own log; with a number like this, don''t wait to measure again.","contact":"Contact your doctor or midwife now; if you can''t reach them or it gets worse, call emergency services (115)."}}}', '[{"op":"and","items":[{"fact":"preg.bp_last_category","op":"eq","value":"severe"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.gdm', 'Pregnancy: blood sugar above the GDM targets', 'worth_followup', 'clinical', 650, 'alerts_inbox', '{"a":{"title":"قند خون بالاتر از محدودهٔ معمول","body":"قند بالاتر از محدودهٔ معمول بارداری ارزش پیگیری داره. عددها رو در ویزیت بعدی به پزشکت نشون بده یا زودتر تماس بگیر."},"seen":"قند ناشتا {preg_fasting} یا بعد از غذا {preg_post_meal} ثبت کردی ({preg_gdm_on})","confidence":"این الگو از ثبت‌های خودته، نه تشخیص","translations":{"en":{"a":{"title":"Blood sugar above the usual range","body":"Sugar above the usual pregnancy range is worth following up. Show the numbers to your doctor at the next visit or call sooner."},"seen":"You logged fasting {preg_fasting} or after-meal {preg_post_meal} ({preg_gdm_on})","confidence":"This pattern comes from your own logs, not a diagnosis"}}}', '[{"op":"and","items":[{"fact":"preg.gdm_last","op":"eq","value":"above_target"}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
('preg.contractions_511', 'Pregnancy: contractions 5-1-1', 'follow_soon', 'safety', 1000, 'alerts_inbox', '{"a":{"title":"انقباض‌ها به الگوی ۵-۱-۱ رسیده","body":"در {preg_labor_minutes} دقیقهٔ گذشته {preg_labor_count} انقباض ثبت کردی؛ فاصلهٔ میانگین {preg_labor_interval} و مدت میانگین {preg_labor_duration}. وقت تماس با زایشگاه یا مامای خودت است؛ وسایل بیمارستان را آماده کن. اگر کیسهٔ آب پاره شد، خون‌ریزی داری یا حرکات جنین کم شده، منتظر نمان."},"seen":"انقباض‌های جلسهٔ {preg_labor_at} به الگوی ۵-۱-۱ رسیده‌اند.","confidence":"این محاسبه از زمان‌هایی است که خودت ثبت کردی؛ فقط معاینه می‌تواند شروع زایمان را تأیید کند","contact":"اگر خون‌ریزی شدید، درد مداوم یا کم‌شدن حرکات جنین داری، همین حالا با اورژانس (۱۱۵) تماس بگیر.","translations":{"en":{"a":{"title":"Your contractions reached the 5-1-1 pattern","body":"You timed {preg_labor_count} contractions in the last {preg_labor_minutes} minutes, on average {preg_labor_interval} apart and {preg_labor_duration} long. It is time to call your maternity unit or midwife and get your hospital bag ready. If your waters break, you are bleeding or the baby moves less, do not wait."},"seen":"The contractions of the session started {preg_labor_at} reached the 5-1-1 pattern.","confidence":"This is worked out from the times you logged; only an exam can confirm that labour has started","contact":"If you have heavy bleeding, constant pain or the baby moves less, call emergency services (115) now."}}}', '[{"op":"and","items":[{"fact":"preg.contractions_511","op":"eq","value":true}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 1, NOW(), NOW()),
('preg.depression', 'Pregnancy: severe depression feelings', 'worth_followup', 'clinical', 560, 'alerts_inbox', '{"a":{"title":"این هفته حالت سخت بوده","body":"لازم نیست تنهایی تحملش کنی. حرف زدن با پزشک، ماما یا یک مشاور کمک می‌کنه. اگه فکر آسیب زدن به خودت به ذهنت می‌رسه، همین حالا با ۱۲۳ یا اورژانس ۱۱۵ تماس بگیر."},"seen":"در ثبت هفتگی ({preg_mood_on}) احساس غم و افسردگی رو «شدید» ثبت کردی","confidence":"این از ثبت خودته، نه تشخیص","translations":{"en":{"a":{"title":"This week has felt hard","body":"You don''t have to carry this alone. Talking to your doctor, midwife or a counsellor helps. If you have thoughts of harming yourself, call 123 or emergency services (115) now."},"seen":"In your weekly log ({preg_mood_on}) you marked feeling low or depressed as \\"severe\\"","confidence":"This comes from your own log, not a diagnosis"}}}', '[{"op":"and","items":[{"fact":"preg.depression_severe","op":"eq","value":true}]}]', '[]', 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW())
ON DUPLICATE KEY UPDATE `id` = `id`;

INSERT INTO `message_inbox` (user_id, rule_id, version, rule_key, slot, kind, level, state, evidence_key, hit_count,
  evidence, first_at, last_at, acked_at, noted_at, resolved_at, archived_at, legacy_alert_id, created_at, updated_at)
SELECT m.user_id, r.id, 1, r.rule_key, 'alerts_inbox', r.kind, r.level, m.state, NULL, 1, m.evidence, m.created_at,
  m.last_at, IF(m.is_dismissed = 1, COALESCE(m.dismissed_at, m.last_at), NULL),
  IF(m.state = 'added_to_visit_note', COALESCE(m.read_at, m.last_at), NULL),
  IF(m.state = 'resolved', NOW(), NULL), IF(m.state = 'archived', NOW(), NULL), m.id, NOW(), NOW()
FROM (
  SELECT x.*,
    CASE
      WHEN x.rn > 1 OR x.old = 1 OR EXISTS (SELECT 1 FROM `message_inbox` o JOIN `message_rules` orr ON orr.id = o.rule_id
             WHERE o.user_id = x.user_id AND orr.rule_key = x.rule_key AND o.open_flag = 1)
        THEN IF(x.old = 1, 'archived', 'resolved')
      WHEN x.is_dismissed = 1 THEN 'acknowledged'
      WHEN x.is_read = 1 THEN 'added_to_visit_note'
      ELSE 'active'
    END AS state
  FROM (
    SELECT k.*, ROW_NUMBER() OVER (PARTITION BY k.user_id, k.rule_key ORDER BY k.created_at DESC, k.id DESC) AS rn,
      IF(k.last_at < NOW() - INTERVAL 30 DAY, 1, 0) AS old
    FROM (
      SELECT a.id, a.user_id, a.is_read, a.is_dismissed, a.read_at, a.dismissed_at, a.created_at,
        COALESCE(a.updated_at, a.created_at) AS last_at,
        CASE SUBSTRING(a.alert_type, 4)
          WHEN 'vomiting_streak' THEN 'preg.vomiting'
          WHEN 'severe_symptom_count' THEN 'preg.severe_symptoms'
          WHEN 'critical_symptom' THEN 'preg.critical_symptom'
          WHEN 'weight_missing_week' THEN 'preg.weight_missing'
          WHEN 'week_entered' THEN 'preg.week_entered'
          WHEN 'sugar_high' THEN 'preg.gdm'
          WHEN 'contractions_511' THEN 'preg.contractions_511'
          WHEN 'fetal_movement' THEN IF(JSON_VALUE(a.trigger_symptoms, '$.variant') = 'kicks', 'preg.fetal_movement_kicks', 'preg.fetal_movement')
          WHEN 'bp_high' THEN IF(JSON_VALUE(a.trigger_symptoms, '$.variant') = 'severe', 'preg.bp_severe',
            IF(COALESCE(JSON_VALUE(a.trigger_symptoms, '$.level4'), '') = 'urgent', 'preg.bp_high_urgent', 'preg.bp_high'))
        END AS rule_key,
        JSON_OBJECT('vars', JSON_MERGE_PATCH(
          JSON_OBJECT('preg_week', a.pregnancy_week),
          CASE SUBSTRING(a.alert_type, 4)
            WHEN 'vomiting_streak' THEN JSON_OBJECT('preg_vomit_days', JSON_VALUE(a.trigger_symptoms, '$.vars.days'), 'preg_vomit_severe', JSON_VALUE(a.trigger_symptoms, '$.vars.severe_count'))
            WHEN 'severe_symptom_count' THEN JSON_OBJECT('preg_severe_count', JSON_VALUE(a.trigger_symptoms, '$.vars.count'))
            WHEN 'critical_symptom' THEN JSON_OBJECT('preg_symptoms', JSON_ARRAY(JSON_VALUE(a.trigger_symptoms, '$.vars.symptom')), 'preg_symptom_on', COALESCE(JSON_VALUE(a.trigger_symptoms, '$.on'), DATE_FORMAT(a.created_at, '%Y-%m-%d')))
            WHEN 'weight_missing_week' THEN JSON_OBJECT('preg_week', JSON_VALUE(a.trigger_symptoms, '$.vars.week'))
            WHEN 'week_entered' THEN JSON_OBJECT('preg_week', JSON_VALUE(a.trigger_symptoms, '$.vars.week'), 'preg_basis', JSON_VALUE(a.trigger_symptoms, '$.vars.basis'),
              'preg_week_on', COALESCE(JSON_VALUE(a.trigger_symptoms, '$.on'), DATE_FORMAT(a.created_at, '%Y-%m-%d')))
            WHEN 'sugar_high' THEN JSON_OBJECT('preg_fasting', IF(CHAR_LENGTH(JSON_VALUE(a.trigger_symptoms, '$.vars.fasting')) = 5 AND JSON_VALUE(a.trigger_symptoms, '$.vars.fasting') LIKE '%none', '—', JSON_VALUE(a.trigger_symptoms, '$.vars.fasting')), 'preg_post_meal', IF(CHAR_LENGTH(JSON_VALUE(a.trigger_symptoms, '$.vars.post_meal')) = 5 AND JSON_VALUE(a.trigger_symptoms, '$.vars.post_meal') LIKE '%none', '—', JSON_VALUE(a.trigger_symptoms, '$.vars.post_meal')), 'preg_gdm_on', COALESCE(JSON_VALUE(a.trigger_symptoms, '$.on'), DATE_FORMAT(a.created_at, '%Y-%m-%d')))
            WHEN 'contractions_511' THEN JSON_OBJECT('preg_labor_count', JSON_VALUE(a.trigger_symptoms, '$.vars.count'), 'preg_labor_minutes', JSON_VALUE(a.trigger_symptoms, '$.vars.minutes'),
              'preg_labor_interval', JSON_VALUE(a.trigger_symptoms, '$.vars.interval'), 'preg_labor_duration', JSON_VALUE(a.trigger_symptoms, '$.vars.duration'), 'preg_labor_at', DATE_FORMAT(a.created_at, '%Y-%m-%d %H:%i'))
            WHEN 'fetal_movement' THEN IF(JSON_VALUE(a.trigger_symptoms, '$.variant') = 'kicks',
              JSON_OBJECT('preg_kick_count', JSON_VALUE(a.trigger_symptoms, '$.vars.count'), 'preg_kick_target', JSON_VALUE(a.trigger_symptoms, '$.vars.target'), 'preg_kick_minutes', JSON_VALUE(a.trigger_symptoms, '$.vars.minutes'), 'preg_kick_at', DATE_FORMAT(a.created_at, '%Y-%m-%d %H:%i')),
              JSON_OBJECT('preg_fetal_status', JSON_VALUE(a.trigger_symptoms, '$.vars.status'), 'preg_fetal_on', COALESCE(JSON_VALUE(a.trigger_symptoms, '$.on'), DATE_FORMAT(a.created_at, '%Y-%m-%d'))))
            WHEN 'bp_high' THEN JSON_OBJECT('preg_bp_sys', IF(CHAR_LENGTH(JSON_VALUE(a.trigger_symptoms, '$.vars.systolic')) = 5 AND JSON_VALUE(a.trigger_symptoms, '$.vars.systolic') LIKE '%none', '—', JSON_VALUE(a.trigger_symptoms, '$.vars.systolic')), 'preg_bp_dia', IF(CHAR_LENGTH(JSON_VALUE(a.trigger_symptoms, '$.vars.diastolic')) = 5 AND JSON_VALUE(a.trigger_symptoms, '$.vars.diastolic') LIKE '%none', '—', JSON_VALUE(a.trigger_symptoms, '$.vars.diastolic')), 'preg_bp_on', COALESCE(JSON_VALUE(a.trigger_symptoms, '$.on'), DATE_FORMAT(a.created_at, '%Y-%m-%d')))
          END)) AS evidence
      FROM `pregnancy_alerts` a
      WHERE a.alert_type LIKE 'v2:%'
        AND NOT EXISTS (SELECT 1 FROM `message_inbox` d WHERE d.legacy_alert_id = a.id)
    ) k
    WHERE k.rule_key IS NOT NULL
  ) x
) m
JOIN `message_rules` r ON r.rule_key = m.rule_key;

-- +goose Down
DELETE FROM `message_inbox` WHERE legacy_alert_id IS NOT NULL;
DELETE FROM `message_rules` WHERE rule_key IN ('preg.vomiting', 'preg.cant_keep_fluids', 'preg.severe_symptoms', 'preg.critical_symptom', 'preg.weight_missing', 'preg.week_entered', 'preg.next_visit', 'preg.fetal_movement', 'preg.fetal_movement_kicks', 'preg.bp_high', 'preg.bp_high_urgent', 'preg.bp_severe', 'preg.gdm', 'preg.contractions_511', 'preg.depression');
